style.css:
@-moz-document url-prefix("https://www.zemomemo.com/private") {
/* Page background */
    body {
        background: #ffffff !important;
        color: #1a1a1a !important;
        font-family: "Helvetica Neue", Arial, sans-serif !important;
    }

    /* Links (Quizlet blue) */
    a, .link {
        color: #4255ff !important;
    }
    a:hover, .link:hover {
        color: #2a3bcc !important;
    }

    /* Headers */
    h1, h2, h3, h4, h5, h6 {
        color: #1a1a1a !important;
        font-weight: 600 !important;
    }

    /* Content cards / boxes */
    .content-box, .card, .box, .panel {
        background: #f9f9f9 !important;
        border-radius: 12px !important;
        box-shadow: 0 2px 6px rgba(0,0,0,0.1) !important;
        padding: 16px !important;
        margin: 12px 0 !important;
    }

    /* Buttons (Quizlet style blue) */
    button, .btn {
        background: #4255ff !important;
        color: #ffffff !important;
        border: none !important;
        border-radius: 8px !important;
        padding: 10px 16px !important;
        font-weight: 600 !important;
        cursor: pointer !important;
    }
    button:hover, .btn:hover {
        background: #2a3bcc !important;
    }

    /* Input fields */
    input, textarea, select {
        border: 1px solid #ddd !important;
        border-radius: 8px !important;
        padding: 8px 12px !important;
        background: #fff !important;
        color: #1a1a1a !important;
    }
}
